/// One Pygments style: the token-to-definition dict its class declares
/// (`pygments/styles/<module>.py`), minus the empty entries `StyleMeta` adds.
pub struct PygmentsStyle {
    pub name: &'static str,
    pub source: &'static str,
    pub definitions: &'static [(&'static str, &'static str)],
}

